import { useEffect, useRef, useState, useSyncExternalStore } from "react";
import { Link } from "react-router";
import { getOverrides, setOverrides, subscribeOverrides, VALUES, type Overrides } from "../content/config";
import { clearProgress, getProgress, subscribeProgress } from "../features/progress/store";
import { getEvents, subscribeEvents } from "../lib/analytics";
import { audioUrl, baseUrl } from "../lib/base";
import { detectInAppBrowser, isStandalone } from "../lib/webview";
import { removeKey, storageWritable } from "../lib/storage";
import { hasMediaSession } from "../features/player/mediaSession";
import { tours } from "../content";
import s from "./DiagnosticsPage.module.css";

const strings = {
  title: "Diagnostyka",
  env: "Środowisko",
  range: "Zasięg bajtów (range requests)",
  rangeRun: "Sprawdź",
  chain: "Odtwarzanie łańcuchowe bez dotknięcia",
  chainHint: "Naciśnij test, zablokuj ekran i odblokuj po około 20 sekundach. Wynik pojawi się w dzienniku.",
  chainA: "Test A: jeden element, zmiana źródła po zakończeniu",
  chainB: "Test B: drugi element odblokowany przy pierwszym dotknięciu",
  variants: "Warianty (ta przeglądarka)",
  reset: "Przywróć domyślne",
  progress: "Postęp",
  clearProgress: "Wyczyść postęp",
  clearOnboarding: "Pokaż ponownie powitanie",
  events: "Zdarzenia",
  links: "Odnośniki",
  qr: "Arkusz kodów QR",
  log: "Dziennik testów",
  clearLog: "Wyczyść dziennik",
  labels: { chapterEnd: "Koniec rozdziału", navigationTarget: "Cel „Nawiguj mnie”", transcriptMode: "Treść słuchowiska", progressTtl: "Pamięć postępu" },
  defaultOpt: "domyślnie",
};

function Row({ k, v }: { k: string; v: string | boolean | number }) {
  return <tr><th scope="row">{k}</th><td>{String(v)}</td></tr>;
}

export function DiagnosticsPage() {
  const overrides = useSyncExternalStore(subscribeOverrides, getOverrides, getOverrides);
  const progress = useSyncExternalStore(subscribeProgress, getProgress, getProgress);
  const events = useSyncExternalStore(subscribeEvents, getEvents, getEvents);
  const [log, setLog] = useState<string[]>([]);
  const [range, setRange] = useState<string>("");
  const [online, setOnline] = useState(navigator.onLine);
  const a1 = useRef<HTMLAudioElement | null>(null);
  const a2 = useRef<HTMLAudioElement | null>(null);
  const add = (m: string) => setLog((l) => [`${new Date().toLocaleTimeString()} ${m}`, ...l].slice(0, 100));

  useEffect(() => {
    const on = () => setOnline(true); const off = () => setOnline(false);
    window.addEventListener("online", on); window.addEventListener("offline", off);
    return () => { window.removeEventListener("online", on); window.removeEventListener("offline", off); };
  }, []);

  const checkRange = async () => {
    try {
      const r = await fetch(audioUrl("ch1-transition.mp3"), { headers: { Range: "bytes=0-1" }, cache: "no-store" });
      setRange(`HTTP ${r.status}, Accept-Ranges: ${r.headers.get("accept-ranges") ?? "brak"}, Content-Range: ${r.headers.get("content-range") ?? "brak"}`);
    } catch (e) { setRange(`błąd: ${String(e)}`); }
  };

  const clipA = audioUrl("ch1-transition.mp3"); const clipB = audioUrl("ch2-transition.mp3");
  const testA = () => {
    const a = (a1.current ??= document.createElement("audio"));
    a.src = clipA; a.onended = () => {
      add("A: pierwszy klip zakończony, zmiana źródła i play()");
      a.onended = () => add("A: drugi klip zakończony. SUKCES");
      a.src = clipB; a.play().then(() => add("A: play() drugiego klipu przyjęte"), (e: unknown) => add(`A: play() odrzucone: ${e instanceof Error ? e.name : String(e)}`));
    };
    a.play().then(() => add("A: start pierwszego klipu"), (e: unknown) => add(`A: start odrzucony: ${e instanceof Error ? e.name : String(e)}`));
  };
  const testB = () => {
    const a = (a1.current ??= document.createElement("audio"));
    const b = (a2.current ??= document.createElement("audio"));
    b.src = clipB; b.muted = true;
    b.play().then(() => { b.pause(); b.muted = false; b.currentTime = 0; add("B: drugi element odblokowany"); }, (e: unknown) => add(`B: odblokowanie drugiego odrzucone: ${e instanceof Error ? e.name : String(e)}`));
    a.src = clipA; a.onended = () => {
      add("B: pierwszy klip zakończony, play() na drugim elemencie");
      b.onended = () => add("B: drugi klip zakończony. SUKCES");
      b.play().then(() => add("B: play() drugiego przyjęte"), (e: unknown) => add(`B: play() drugiego odrzucone: ${e instanceof Error ? e.name : String(e)}`));
    };
    a.play().then(() => add("B: start pierwszego klipu"), (e: unknown) => add(`B: start odrzucony: ${e instanceof Error ? e.name : String(e)}`));
  };

  const setOv = (k: keyof Overrides, v: string) => {
    const next = { ...overrides } as Record<string, string | undefined>;
    if (v === "") delete next[k]; else next[k] = v;
    setOverrides(next as Overrides);
  };
  const tour = tours[0]!;

  return (
    <main className={s.main}>
      <h1 className="h1">{strings.title}</h1>

      <section className={s.card}><h2 className="h3">{strings.env}</h2>
        <table className={s.table}><tbody>
          <Row k="userAgent" v={navigator.userAgent} />
          <Row k="online" v={online} />
          <Row k="standalone" v={isStandalone()} />
          <Row k="in-app browser" v={detectInAppBrowser() ?? "nie"} />
          <Row k="localStorage" v={storageWritable()} />
          <Row k="mediaSession" v={hasMediaSession()} />
          <Row k="geolocation" v={"geolocation" in navigator} />
          <Row k="BroadcastChannel" v={"BroadcastChannel" in window} />
          <Row k="secure context" v={window.isSecureContext} />
          <Row k="base" v={baseUrl} />
          <Row k="build" v={__BUILD_TIME__} />
        </tbody></table>
      </section>

      <section className={s.card}><h2 className="h3">{strings.range}</h2>
        <div className={s.actions}><button type="button" className={s.btn} onClick={checkRange}>{strings.rangeRun}</button><span className={s.mono}>{range}</span></div>
      </section>

      <section className={s.card}><h2 className="h3">{strings.chain}</h2>
        <p className="h5">{strings.chainHint}</p>
        <div className={s.actions}>
          <button type="button" className={s.btn} onClick={testA}>{strings.chainA}</button>
          <button type="button" className={s.btn} onClick={testB}>{strings.chainB}</button>
        </div>
        <h3 className="h4">{strings.log}</h3>
        <ul className={s.log}>{log.map((l, i) => <li key={i} className={s.mono}>{l}</li>)}</ul>
        <button type="button" className={s.btn} onClick={() => setLog([])}>{strings.clearLog}</button>
      </section>

      <section className={s.card}><h2 className="h3">{strings.variants}</h2>
        <div className={s.form}>
          {(Object.keys(VALUES) as Array<keyof typeof VALUES>).map((k) => (
            <label key={k} className={s.field}>
              <span>{strings.labels[k]}</span>
              <select value={overrides[k] ?? ""} onChange={(e) => setOv(k, e.target.value)}>
                <option value="">{`${strings.defaultOpt} (${k === "progressTtl" ? "none" : tour.config[k]})`}</option>
                {VALUES[k].map((v) => <option key={v} value={v}>{v}</option>)}
              </select>
            </label>
          ))}
        </div>
        <button type="button" className={s.btn} onClick={() => setOverrides({})}>{strings.reset}</button>
      </section>

      <section className={s.card}><h2 className="h3">{strings.progress}</h2>
        <pre className={s.pre}>{JSON.stringify(progress, null, 1)}</pre>
        <div className={s.actions}>
          <button type="button" className={s.btn} onClick={() => clearProgress()}>{strings.clearProgress}</button>
          <button type="button" className={s.btn} onClick={() => removeKey("krzemien.onboarding.v1")}>{strings.clearOnboarding}</button>
        </div>
      </section>

      <section className={s.card}><h2 className="h3">{strings.events}</h2>
        <ul className={s.log}>{events.map((e, i) => <li key={i} className={s.mono}>{`${e.at.slice(11, 19)} ${e.name} ${JSON.stringify(e.props)}`}</li>)}</ul>
      </section>

      <section className={s.card}><h2 className="h3">{strings.links}</h2>
        <ul className={s.links}>
          <li><Link to="/qr">{strings.qr}</Link></li>
          {tour.chapters.map((c) => <li key={c.id}><Link to={`/q/${c.qrToken}`}>{`/q/${c.qrToken}`}</Link> <span className={s.mono}>{`· ${c.title}`}</span></li>)}
        </ul>
      </section>
    </main>
  );
}
